package com.kitex.mom.wms.service.impl;

import cn.hutool.core.util.StrUtil;
import com.kitex.mom.wms.service.inventoryapproval.WmsInventoryApprovalExecutionContext;
import com.kitex.common.security.component.PermissionService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

/**
 * Matches the warehouse-specific button codes generated by warehouse menu synchronization.
 */
@Component
@RequiredArgsConstructor
public class WmsInventoryWarehousePermission {
    private static final String PREFIX = "wms_wmsInsideInventoryPlan_";

    private final PermissionService permissions;

    public void require(String action, String warehouseCode) {
        String base = PREFIX + action;
        String warehouse = StrUtil.trim(warehouseCode);
        boolean allowed = permissions.hasPermission(base);
        if (StrUtil.isNotBlank(warehouse)) {
            WmsInventoryPlanAccess.require(!warehouse.contains("*"), "仓库编码不正确");
            allowed = allowed || permissions.hasPermission(base + "_" + warehouse);
        }
        if ("entry".equals(action) || "hand".equals(action)) {
            allowed = allowed || permissions.hasPermission(PREFIX + "edit");
        }
		// 只桥接已核实际组织/仓/明细且持有事务锁的本次恢复申请；不放宽旧入口edit或其它动作。
		if ("hand".equals(action)) {
			allowed = allowed || WmsInventoryApprovalExecutionContext.submitWarehouseHand(warehouseCode);
		}
        WmsInventoryPlanAccess.require(allowed, "无该仓库盘点" + actionName(action) + "权限");
    }

    private String actionName(String action) {
        return switch (action) {
            case "view" -> "查看";
            case "add" -> "新增";
            case "entry" -> "录入";
            case "hand" -> "损益处理";
            case "del" -> "删除";
            case "cancel" -> "作废";
            case "export" -> "导出";
            default -> "操作";
        };
    }
}
